using LabMetricsDashboard.Models;
using LabMetricsDashboard.Services;
using LRN.ReportWorker.Generators;

namespace LRN.SnapshotGenerator;

/// <summary>
/// The Denial Summary page's Denial Insight tab, both of its views: the Current Week and Previous Week
/// rows. Not generated by any service - the client uploads and edits it - so it is captured on
/// LabMetricsDashboard's request (dbo.ReportSnapshotRequest), not on a tracker Success. A viewer builds
/// the page's DenialInsightPanelViewModel from it (Bucket, Rows, CurrentWeekStart, BucketCounts).
/// </summary>
public sealed class DenialInsightSnapshotModel
{
    public string CurrentLab { get; set; } = "";
    public DateTime CurrentWeekStart { get; set; }
    public Dictionary<string, int> BucketCounts { get; set; } = new(StringComparer.Ordinal);
    public IReadOnlyList<DenialInsightRow> CurrentWeek { get; set; } = [];
    public IReadOnlyList<DenialInsightRow> PreviousWeek { get; set; } = [];
}

public sealed class DenialInsightSnapshotSource : IReportSnapshotSource
{
    private readonly LabSettings _labSettings;
    private readonly SqlDenialClaimReportRepository _repo;
    private readonly LabConfigOptions _labConfig;

    public DenialInsightSnapshotSource(LabSettings labSettings, SqlDenialClaimReportRepository repo, LabConfigOptions labConfig)
    {
        _labSettings = labSettings;
        _repo = repo;
        _labConfig = labConfig;
    }

    public string SnapshotReportCode => ReportSnapshotCodes.DenialInsight;

    public async Task<object?> LoadUnfilteredAsync(string labName, CancellationToken ct)
    {
        if (!_labSettings.Labs.TryGetValue(labName, out var labConfig) || string.IsNullOrWhiteSpace(labConfig.DbConnectionString))
            return null;
        var connStr = labConfig.DbConnectionString;

        // The same week the page dates Current Week by (LabConfig:DenialSummaryWeekRange).
        var weekStart = SqlDenialClaimReportRepository.WeekStartOf(DateTime.Today,
            _labConfig.GetDenialSummaryWeekStart(labName) ?? SqlDenialClaimReportRepository.DefaultWeekStartsOn);
        return new DenialInsightSnapshotModel
        {
            CurrentLab = labName,
            CurrentWeekStart = weekStart,
            BucketCounts = new Dictionary<string, int>(await _repo.GetInsightCountsAsync(connStr, ct), StringComparer.Ordinal),
            CurrentWeek = await _repo.GetInsightsAsync(connStr, DenialInsightBuckets.Current, ct),
            PreviousWeek = await _repo.GetInsightsAsync(connStr, DenialInsightBuckets.Previous, ct)
        };
    }
}
